mapper.update:
UPDATE member
SET password_hash = #{passwordHash}, updated_at = #{updatedAt}
WHERE member_id = #{memberId}

mapper.select:
SELECT member_id, email, nickname, created_at
FROM member
WHERE member_id = #{memberId}

SELECT member_id, email, withdrawn_at FROM member
WHERE withdrawn_at IS NOT NULL AND withdrawn_at <= #{cutoff}
ORDER BY withdrawn_at, member_id LIMIT #{limit} FOR UPDATE
